Here's a pytest test suite for your `slugify` function:

```python
import pytest

from mymodule import slugify  # adjust import to match your module


class TestSlugifyBasic:
    def test_simple_word(self):
        assert slugify("Hello") == "hello"

    def test_two_words(self):
        assert slugify("Hello World") == "hello-world"

    def test_already_slugified(self):
        assert slugify("hello-world") == "hello-world"

    def test_multiple_spaces(self):
        assert slugify("hello   world") == "hello---world"

    def test_leading_and_trailing_spaces(self):
        assert slugify("  hello world  ") == "--hello-world--"


class TestSlugifyCase:
    def test_all_uppercase(self):
        assert slugify("HELLO WORLD") == "hello-world"

    def test_mixed_case(self):
        assert slugify("Hello World Foo") == "hello-world-foo"

    def test_digits_unchanged(self):
        assert slugify("Page 42") == "page-42"


class TestSlugifyEdgeCases:
    def test_empty_string(self):
        assert slugify("") == ""

    def test_single_space(self):
        assert slugify(" ") == "-"

    def test_special_characters_preserved(self):
        # documents current behavior: punctuation passes through untouched
        assert slugify("Hello, World!") == "hello,-world!"

    def test_unicode_lowercasing(self):
        # Python's .lower() handles non-ASCII characters
        assert slugify("Héllo Wörld") == "héllo-wörld"


class TestSlugifyTypes:
    @pytest.mark.parametrize("bad_input", [None, 123, ["a", "b"], 3.14])
    def test_non_string_input_raises(self, bad_input):
        with pytest.raises(AttributeError):
            slugify(bad_input)


class TestSlugifyRealistic:
    @pytest.mark.parametrize(
        "raw,expected",
        [
            ("My Blog Post Title", "my-blog-post-title"),
            ("10 Tips for Better Sleep", "10-tips-for-better-sleep"),
            ("a", "a"),
        ],
    )
    def test_typical_inputs(self, raw, expected):
        assert slugify(raw) == expected
```

A few notes on what these tests cover and why:

1. **Happy path** — typical titles convert as expected.
2. **Edge cases** — empty strings, repeated/leading/trailing spaces, and single characters. These are where `str.replace`-based slugifiers often surprise people (e.g., `"hello  world"` becomes `"hello--world"`, not `"hello-world"`).
3. **Characterization tests** — `test_special_characters_preserved` documents that punctuation isn't stripped or escaped. If you later "fix" this, the test failing is a good signal to update it intentionally.
4. **Type errors** — non-string inputs raise `AttributeError` because `.lower()` doesn't exist on them. If you want a friendlier API, you could change the function to `return str(s).lower().replace(' ', '-')` and update this test to assert coercion instead.

If any of the edge-case behaviors (multiple dashes, preserved punctuation) aren't what you actually want, the function itself probably needs a tweak rather than the tests — happy to help with a more robust version (e.g., one that collapses whitespace and strips punctuation).
